    <div className="card p-5 mb-6"><div className="flex justify-between text-sm mb-3"><span className="font-semibold">Overall progress</span><span className="text-emerald-300">{r.completionPercentage}%</span></div><div className="progress-track !h-2"><div className="progress-fill" style={{width:`${r.completionPercentage}%`}}/></div><div className="flex flex-wrap gap-2 mt-4">{(r.content?.toolsAndTechnologies||[]).slice(0,8).map((x:string)=><span key={x} className="rounded-full bg-[#222942] text-slate-300 px-3 py-1 text-[11px]">{x}</span>)}</div></div>
