    {resources.length>0&&<div className="flex flex-wrap gap-2 mb-5">{filters.map(f=><button key={f} onClick={()=>setFilter(f)} className={cls('select-chip',filter===f&&'selected')} data-testid={`button-resource-filter-${String(f).toLowerCase().replaceAll(' ','-')}`}>{f}</button>)}</div>}
